import{_ as p,a0 as e,w as r,s as u,ao as o,I as s,x as a,a1 as n,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"在你开始使用 Kali Linux 之前必须知道的事情 | LCTT x X-CMD","titleTemplate":false,"description":"在你开始使用 Kali Linux 之前必须知道的事情 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在你开始使用 Kali Linux 之前必须知道的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在你开始使用 Kali Linux 之前必须知道的事情 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181015 Kali Linux- What You Must Know Before Using it - FOSS Post","title":"在你开始使用 Kali Linux 之前必须知道的事情","tag":"201811","desc":""},"relativePath":"201811/20181015 Kali Linux- What You Must Know Before Using it - FOSS Post.md","filePath":"[post].md"}'),x={name:"201811/20181015 Kali Linux- What You Must Know Before Using it - FOSS Post.md"};function d(L,i,K,f,m,g){const t=e("Link");return r(),u("div",null,[i[26]||(i[26]=o('<h1 id="在你开始使用-kali-linux-之前必须知道的事情" tabindex="-1">在你开始使用 Kali Linux 之前必须知道的事情 <a class="header-anchor" href="#在你开始使用-kali-linux-之前必须知道的事情" aria-label="Permalink to “在你开始使用 Kali Linux 之前必须知道的事情”">​</a></h1><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2018/10/kali-linux.png?fit=1237%2C527&amp;ssl=1" alt=""></p><p>Kali Linux 在渗透测试和白帽子方面是业界领先的 Linux 发行版。默认情况下，该发行版附带了大量入侵和渗透的工具和软件，并且在全世界都得到了广泛认可。即使在那些甚至可能不知道 Linux 是什么的 Windows 用户中也是如此。</p><p>由于后者的原因（LCTT 译注：Windows 用户），许多人都试图单独使用 Kali Linux，尽管他们甚至不了解 Linux 系统的基础知识。原因可能各不相同，有的为了玩乐，有的是为了取悦女友而伪装成黑客，有的仅仅是试图破解邻居的 WiFi 网络以免费上网。如果你打算使用 Kali Linux，记住，所有的这些都是不好的事情。</p><p>在计划使用 Kali Linux 之前，你应该了解一些提示。</p><h3 id="kali-linux-不适合初学者" tabindex="-1">Kali Linux 不适合初学者 <a class="header-anchor" href="#kali-linux-不适合初学者" aria-label="Permalink to “Kali Linux 不适合初学者”">​</a></h3><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2018/10/Kali-Linux-000.png?resize=850%2C478&amp;ssl=1" alt=""></p><p><em>Kali Linux 默认 GNOME 桌面</em></p><p>如果你是几个月前刚开始使用 Linux 的人，或者你认为自己的知识水平低于平均水平，那么 Kali Linux 就不适合你。如果你打算问“如何在 Kali 上安装 Steam？如何让我的打印机在 Kali 上工作？如何解决 Kali 上的 APT 源错误？”这些东西，那么 Kali Linux 并不适合你。</p><p>Kali Linux 主要面向想要运行渗透测试套件的专家或想要学习成为白帽子和数字取证的人。但即使你属于后者，普通的 Kali Linux 用户在日常使用时也会遇到很多麻烦。他还被要求以非常谨慎的方式使用工具和软件，而不仅仅是“让我们安装并运行一切”。每一个工具必须小心使用，你安装的每一个软件都必须仔细检查。</p>',10)),s("p",null,[i[1]||(i[1]=s("strong",null,"建议阅读：",-1)),i[2]||(i[2]=a()),n(t,{href:"https://fosspost.org/articles/what-are-the-components-of-a-linux-distribution"},{default:l(()=>[...i[0]||(i[0]=[a("Linux 系统的组件有什么?",-1)])]),_:1})]),i[27]||(i[27]=o('<p>普通 Linux 用户都无法自如地使用它。一个更好的方法是花几周时间学习 Linux 及其守护进程、服务、软件、发行版及其工作方式，然后观看几十个关于白帽子攻击的视频和课程，然后再尝试使用 Kali 来应用你学习到的东西。</p><h3 id="它会让你被黑客攻击" tabindex="-1">它会让你被黑客攻击 <a class="header-anchor" href="#它会让你被黑客攻击" aria-label="Permalink to “它会让你被黑客攻击”">​</a></h3><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2018/10/Kali-Linux-001.png?resize=850%2C478&amp;ssl=1" alt=""></p><p><em>Kali Linux 入侵和测试工具</em></p><p>在普通的 Linux 系统中，普通用户有一个账户，而 root 用户也有一个单独的账号。但在 Kali Linux 中并非如此。Kali Linux 默认使用 root 账户，不提供普通用户账户。这是因为 Kali 中几乎所有可用的安全工具都需要 root 权限，并且为了避免每分钟要求你输入 root 密码，所以这样设计。</p><p>当然，你可以简单地创建一个普通用户账户并开始使用它。但是，这种方式仍然不推荐，因为这不是 Kali Linux 系统设计的工作方式。使用普通用户在使用程序，打开端口，调试软件时，你会遇到很多问题，你会发现为什么这个东西不起作用，最终却发现它是一个奇怪的权限错误。另外每次在系统上做任何事情时，你会被每次运行工具都要求输入密码而烦恼。</p><p>现在，由于你被迫以 root 用户身份使用它，因此你在系统上运行的所有软件也将以 root 权限运行。如果你不知道自己在做什么，那么这很糟糕，因为如果 Firefox 中存在漏洞，并且你访问了一个受感染的网站，那么黑客能够在你的 PC 上获得全部 root 权限并入侵你。如果你使用的是普通用户账户，则会受到限制。此外，你安装和使用的某些工具可能会在你不知情的情况下打开端口并泄露信息，因此如果你不是非常小心，人们可能会以你尝试入侵他们的方式入侵你。</p><p>如果你曾经访问过与 Kali Linux 相关的 Facebook 群组，你会发现这些群组中几乎有四分之一的帖子是人们在寻求帮助，因为有人入侵了他们。</p><h3 id="它可以让你入狱" tabindex="-1">它可以让你入狱 <a class="header-anchor" href="#它可以让你入狱" aria-label="Permalink to “它可以让你入狱”">​</a></h3><p>Kali Linux 只是提供了软件。那么，如何使用它们完全是你自己的责任。</p><p>在世界上大多数发达国家，使用针对公共 WiFi 网络或其他设备的渗透测试工具很容易让你入狱。现在不要以为你使用了 Kali 就无法被跟踪，许多系统都配置了复杂的日志记录设备来简单地跟踪试图监听或入侵其网络的人，你可能无意间成为其中的一个，那么它会毁掉你的生活。</p><p>永远不要对不属于你的设备或网络使用 Kali Linux 系统，也不要明确允许对它们进行入侵。如果你说你不知道你在做什么，在法庭上它不会被当作借口来接受。</p><h3 id="修改了的内核和软件" tabindex="-1">修改了的内核和软件 <a class="header-anchor" href="#修改了的内核和软件" aria-label="Permalink to “修改了的内核和软件”">​</a></h3>',13)),s("p",null,[i[4]||(i[4]=a("Kali ",-1)),n(t,{href:"https://www.kali.org/news/kali-linux-rolling-edition-2016-1/"},{default:l(()=>[...i[3]||(i[3]=[a("基于",-1)])]),_:1}),i[5]||(i[5]=a(" Debian（“测试”分支，这意味着 Kali Linux 使用滚动发布模型），因此它使用了 Debian 的大部分软件体系结构，你会发现 Kali Linux 中的大部分软件跟 Debian 中的没什么区别。",-1))]),i[28]||(i[28]=o(`<p>但是，Kali 修改了一些包来加强安全性并修复了一些可能的漏洞。例如，Kali 使用的 Linux 内核被打了补丁，允许在各种设备上进行无线注入。这些补丁通常在普通内核中不可用。此外，Kali Linux 不依赖于 Debian 服务器和镜像，而是通过自己的服务器构建软件包。以下是最新版本中的默认软件源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://http.kali.org/kali kali-rolling main contrib non-free</span></span>
<span class="line"><span>deb-src http://http.kali.org/kali kali-rolling main contrib non-free</span></span></code></pre></div>`,2)),s("p",null,[i[8]||(i[8]=a("这就是为什么，对于某些特定的软件，当你在 Kali Linux 和 Fedora 中使用相同的程序时，你会发现不同的行为。你可以从 ",-1)),n(t,{href:"http://git.kali.org"},{default:l(()=>[...i[6]||(i[6]=[a("git.kali.org",-1)])]),_:1}),i[9]||(i[9]=a(" 中查看 Kali Linux 软件的完整列表。你还可以在 Kali Linux（GNOME）上找到我们",-1)),n(t,{href:"https://paste.ubuntu.com/p/bctSVWwpVw/"},{default:l(()=>[...i[7]||(i[7]=[a("自己生成的已安装包列表",-1)])]),_:1}),i[10]||(i[10]=a("。",-1))]),i[29]||(i[29]=o('<p>更重要的是，Kali Linux 官方文档极力建议不要添加任何其他第三方软件仓库，因为 Kali Linux 是一个滚动发行版，并且依赖于 Debian 测试分支，由于依赖关系冲突和包钩子，所以你很可能只是添加一个新的仓库源就会破坏系统。</p><h3 id="不要安装-kali-linux" tabindex="-1">不要安装 Kali Linux <a class="header-anchor" href="#不要安装-kali-linux" aria-label="Permalink to “不要安装 Kali Linux”">​</a></h3><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2018/10/Kali-Linux-002.png?resize=750%2C504&amp;ssl=1" alt=""></p><p><em>使用 Kali Linux 在 fosspost.org 上运行 wpscan</em></p><p>我在极少数情况下使用 Kali Linux 来测试我部署的软件和服务器。但是，我永远不敢安装它并将其用作主系统。</p><p>如果你要将其用作主系统，那么你必须保留自己的个人文件、密码、数据以及系统上的所有内容。你还需要安装大量日常使用的软件，以解放你的生活。但正如我们上面提到的，使用 Kali Linux 是非常危险的，应该非常小心地进行，如果你被入侵了，你将丢失所有数据，并且可能会暴露给更多的人。如果你在做一些不合法的事情，你的个人信息也可用于跟踪你。如果你不小心使用这些工具，那么你甚至可能会毁掉自己的数据。</p><p>即使是专业的白帽子也不建议将其作为主系统安装，而是通过 USB 使用它来进行渗透测试工作，然后再回到普通的 Linux 发行版。</p><h3 id="底线" tabindex="-1">底线 <a class="header-anchor" href="#底线" aria-label="Permalink to “底线”">​</a></h3><p>正如你现在所看到的，使用 Kali 并不是一个轻松的决定。如果你打算成为一个白帽子，你需要使用 Kali 来学习，那么在学习了基础知识并花了几个月的时间使用普通 Linux 系统之后再来学习 Kali。但是小心你正在做的事情，以避免遇到麻烦。</p><p>如果你打算使用 Kali，或者你需要任何帮助，我很乐意在评论中听到你的想法。</p><hr>',11)),s("p",null,[i[12]||(i[12]=a("via: ",-1)),n(t,{href:"https://fosspost.org/articles/must-know-before-using-kali-linux"},{default:l(()=>[...i[11]||(i[11]=[a("https://fosspost.org/articles/must-know-before-using-kali-linux",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=a("作者：",-1)),n(t,{href:"https://fosspost.org/author/mhsabbagh"},{default:l(()=>[...i[13]||(i[13]=[a("M.Hanny Sabbagh",-1)])]),_:1}),i[18]||(i[18]=a(" 选题：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[14]||(i[14]=[a("lujun9972",-1)])]),_:1}),i[19]||(i[19]=a(" 译者：",-1)),n(t,{href:"https://github.com/MjSeven"},{default:l(()=>[...i[15]||(i[15]=[a("MjSeven",-1)])]),_:1}),i[20]||(i[20]=a(" 校对：",-1)),n(t,{href:"https://github.com/wxy"},{default:l(()=>[...i[16]||(i[16]=[a("wxy",-1)])]),_:1})]),s("p",null,[i[23]||(i[23]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[21]||(i[21]=[a("LCTT",-1)])]),_:1}),i[24]||(i[24]=a(" 原创编译，",-1)),n(t,{href:"https://linux.cn/"},{default:l(()=>[...i[22]||(i[22]=[a("Linux中国",-1)])]),_:1}),i[25]||(i[25]=a(" 荣誉推出",-1))])])}const h=p(x,[["render",d]]);export{k as __pageData,h as default};
